from __future__ import annotations

CONTROL_UI = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>TITAN · Ableton Production Console</title>
<style>
:root{color-scheme:dark;--bg:#080a0b;--panel:#111518;--line:#293137;--text:#eef2f3;--muted:#88949b;--green:#61f2b5;--amber:#f1b84b;--red:#ff6969;--blue:#6ea8ff;font-family:Inter,Segoe UI,system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#12231d 0,transparent 28%),var(--bg);color:var(--text)}button,input,textarea{font:inherit}.wrap{max-width:1500px;margin:auto;padding:24px}.top,.row,.head{display:flex;gap:12px;align-items:center;justify-content:space-between}.top{align-items:flex-start;margin-bottom:18px}.eyebrow{color:var(--green);font-size:11px;font-weight:800;letter-spacing:.18em}h1{margin:5px 0;font-size:28px}h2{font-size:17px;margin:0}.muted{color:var(--muted);font-size:12px}.pills{display:flex;gap:8px;flex-wrap:wrap}.pill,.badge{border:1px solid var(--line);border-radius:999px;padding:7px 10px;font-size:10px;color:var(--muted)}.confirmed{color:var(--green);border-color:#265942}.pending{color:var(--amber);border-color:#624c21}.error{color:var(--red);border-color:#6b2b2b}.card{background:linear-gradient(180deg,#171c20,var(--panel));border:1px solid var(--line);border-radius:12px;padding:15px}.grid{display:grid;gap:11px}.metrics{grid-template-columns:repeat(4,1fr)}.metric b{display:block;font-size:20px;margin-top:6px}.toolbar{margin:14px 0;display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid var(--line);background:#20262a;color:white;border-radius:8px;padding:9px 13px;cursor:pointer;font-weight:700}.btn.primary{background:var(--green);color:#07120d;border-color:transparent}.btn.amber{background:var(--amber);color:#171005;border-color:transparent}.btn:disabled{opacity:.45;cursor:not-allowed}.tempo{width:90px;background:#0b0e10;border:1px solid var(--line);color:white;border-radius:8px;padding:9px}.section{margin-top:24px}.section .head{margin-bottom:10px}.mixer{grid-template-columns:repeat(4,minmax(210px,1fr))}.returns{grid-template-columns:repeat(4,minmax(210px,1fr))}.name{font-weight:800}.control{margin-top:10px}.control label{display:flex;justify-content:space-between;color:var(--muted);font-size:10px}.control input{width:100%;accent-color:var(--green)}.sends{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:10px}.sends label{font-size:9px;color:var(--muted)}.sends input{width:100%;accent-color:var(--blue)}.actions{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:10px}.mini{border:1px solid var(--line);background:#1a2024;color:#c5ced2;border-radius:6px;padding:7px;font-size:10px;cursor:pointer}.mini.onM{background:var(--amber);color:#171005}.mini.onS{background:var(--green);color:#07120d}.history{display:flex;flex-direction:column;gap:7px}.event{display:grid;grid-template-columns:150px 1fr auto;gap:12px;padding:10px;background:#101417;border:1px solid var(--line);border-radius:8px;font-size:11px}.notice{margin-top:14px;padding:12px;border:1px solid #624c21;background:#241d10;color:#f3cf85;border-radius:9px;font-size:12px}.global-error{color:var(--red);font-size:12px;margin:8px 0}@media(max-width:1050px){.mixer{grid-template-columns:repeat(2,1fr)}.returns,.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.wrap{padding:15px}.top{flex-direction:column}.mixer,.returns,.metrics{grid-template-columns:1fr}.event{grid-template-columns:1fr}.actions{grid-template-columns:repeat(2,1fr)}}
</style></head><body><main class="wrap">
<header class="top"><div><div class="eyebrow">TITAN PRODUCTION SYSTEM</div><h1>Ableton Live 11 Control Console</h1><div class="muted">Targets are presets. Confirmed means Ableton returned an ACK.</div></div><div class="pills"><span id="bridgePill" class="pill pending">Bridge checking</span><span id="receiverPill" class="pill pending">Receiver checking</span><span id="modePill" class="pill">Mode</span></div></header>
<div id="globalError" class="global-error"></div>
<section class="grid metrics"><div class="card metric"><span class="muted">Bridge</span><b id="bridgeMetric">—</b></div><div class="card metric"><span class="muted">Ableton ACK</span><b id="receiverMetric">—</b></div><div class="card metric"><span class="muted">Commands</span><b id="commandMetric">0</b></div><div class="card metric"><span class="muted">Last ACK</span><b id="ackMetric">—</b></div></section>
<div class="card toolbar"><button class="btn primary" onclick="simple('start_playback')">PLAY</button><button class="btn" onclick="simple('stop_playback')">STOP</button><input id="tempo" class="tempo" type="number" value="128" min="20" max="300"><button class="btn" onclick="setTempo()">SET TEMPO</button><button class="btn amber" onclick="applyPremix()">APPLY FULL PREMIX</button><button class="btn" onclick="refreshAll()">REFRESH</button></div>
<section class="section"><div class="head"><div><h2>12-Stem Mixer</h2><div class="muted">Apply Mix sends volume + pan. Apply Sends sends A–D. Mute and Solo are reversible.</div></div></div><div id="mixerGrid" class="grid mixer"></div></section>
<section class="section"><div class="head"><div><h2>Return Controls</h2><div class="muted">Stable indices: A=0, B=1, C=2, D=3.</div></div></div><div id="returnGrid" class="grid returns"></div></section>
<section class="section"><div class="card"><div class="head"><div><h2>Master Chain</h2><div class="muted">EQ Eight → Glue Compressor → Saturator → Limiter</div></div><span class="badge">NOT AUTOMATED</span></div><div class="notice">Documented target only. Titan will not claim or apply Master settings until dedicated master-device commands and readback exist.</div></div></section>
<section class="section"><div class="head"><div><h2>Recent Activity</h2><div class="muted">Command state, ACK and errors.</div></div><button class="btn" onclick="loadHistory()">REFRESH</button></div><div id="historyList" class="history"></div></section>
</main><script>
const stems=[
{ref:'kick',name:'01 KICK',vol:.82,pan:0,sends:[0,.01,.01,.08]},{ref:'bass',name:'02 ROUND BASS',vol:.72,pan:0,sends:[.02,.02,.01,.03]},{ref:'percussion',name:'03 PERCUSSION',vol:.56,pan:-.08,sends:[.14,.03,.02,.18]},{ref:'groove_hats',name:'04 GROOVE HAT',vol:.48,pan:.12,sends:[.10,.03,.02,.08]},{ref:'open_hats',name:'05 OPEN HAT',vol:.42,pan:-.16,sends:[.13,.05,.04,.02]},{ref:'synth_stab',name:'06 SYNTH STAB',vol:.46,pan:.08,sends:[.08,.10,.07,.11]},{ref:'melody',name:'07 MELODY',vol:.43,pan:-.06,sends:[.07,.12,.09,.03]},{ref:'pad',name:'08 PAD',vol:.34,pan:.12,sends:[.04,.04,.16,.01]},{ref:'fx_riser',name:'09 FX RISER',vol:.34,pan:-.18,sends:[.04,.08,.14,0]},{ref:'fx_impact',name:'10 FX IMPACT',vol:.40,pan:.14,sends:[.06,.03,.08,.04]},{ref:'voice',name:'11 VOICE',vol:.44,pan:0,sends:[.12,.15,.12,.03]},{ref:'ambient',name:'12 AMBIENT',vol:.30,pan:.18,sends:[.03,.03,.20,0]}];
const returns=[{i:0,l:'A',name:'SHORT ROOM',desc:'Reverb · short cohesion',vol:.34,pan:0},{i:1,l:'B',name:'DUB DELAY',desc:'Echo · tempo-synced stereo delay',vol:.28,pan:0},{i:2,l:'C',name:'LONG SPACE',desc:'Hybrid Reverb · long tail',vol:.24,pan:0},{i:3,l:'D',name:'PARALLEL DRIVE',desc:'Drum Buss / Glue · parallel density',vol:.20,pan:0}];
let commands=[],busy=false;const token=document.querySelector('#token');const params=new URLSearchParams(location.search);if(params.get('token')){localStorage.bridgeToken=params.get('token');history.replaceState({},'',location.pathname)}
const headers=()=>({'Content-Type':'application/json','X-Bridge-Token':localStorage.bridgeToken||''});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function stateFor(fn){const c=commands.find(fn);if(!c)return 'target';if(c.status==='acknowledged'||c.status==='simulated')return 'confirmed';if(c.status==='error'||c.status==='rejected')return 'error';return 'pending'}
function badge(state,label){return `<span class="badge ${state}">${label||state.toUpperCase()}</span>`}
async function send(payload){const r=await fetch('/command',{method:'POST',headers:headers(),body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw Error(d.error||'Command failed');return d.command}
async function batch(items){busy=true;setDisabled();try{for(const item of items)await send(item);document.querySelector('#globalError').textContent='';await refreshAll()}catch(e){document.querySelector('#globalError').textContent=e.message}finally{busy=false;setDisabled()}}
async function simple(type,extra={}){await batch([{type,...extra}])}async function setTempo(){await simple('set_tempo',{bpm:Number(document.querySelector('#tempo').value)})}
function setDisabled(){document.querySelectorAll('button').forEach(b=>b.disabled=busy)}
function renderMixer(){document.querySelector('#mixerGrid').innerHTML=stems.map(s=>{const st=stateFor(c=>['set_track_volume','set_track_pan'].includes(c.command_type)&&c.payload.track_ref===s.ref);return `<article class="card"><div class="head"><span class="name">${s.name}</span>${badge(st)}</div><div class="control"><label><span>Volume target</span><span id="v-${s.ref}">${s.vol.toFixed(2)}</span></label><input type="range" min="0" max="1" step=".01" value="${s.vol}" oninput="stems.find(x=>x.ref==='${s.ref}').vol=+this.value;document.querySelector('#v-${s.ref}').textContent=(+this.value).toFixed(2)"></div><div class="control"><label><span>Pan target</span><span id="p-${s.ref}">${s.pan.toFixed(2)}</span></label><input type="range" min="-1" max="1" step=".01" value="${s.pan}" oninput="stems.find(x=>x.ref==='${s.ref}').pan=+this.value;document.querySelector('#p-${s.ref}').textContent=(+this.value).toFixed(2)"></div><div class="sends">${s.sends.map((v,i)=>`<label>${String.fromCharCode(65+i)} <span id="s-${s.ref}-${i}">${v.toFixed(2)}</span><input type="range" min="0" max="1" step=".01" value="${v}" oninput="stems.find(x=>x.ref==='${s.ref}').sends[${i}]=+this.value;document.querySelector('#s-${s.ref}-${i}').textContent=(+this.value).toFixed(2)"></label>`).join('')}</div><div class="actions"><button class="mini" onclick="applyMix('${s.ref}')">Apply Mix</button><button class="mini" onclick="applySends('${s.ref}')">Apply Sends</button><button id="m-${s.ref}" class="mini" onclick="toggleMute('${s.ref}')">M OFF</button><button id="so-${s.ref}" class="mini" onclick="toggleSolo('${s.ref}')">S OFF</button></div></article>`}).join('');setDisabled()}
async function applyMix(ref){const s=stems.find(x=>x.ref===ref);await batch([{type:'set_track_volume',track_ref:ref,volume:s.vol},{type:'set_track_pan',track_ref:ref,pan:s.pan}])}
async function applySends(ref){const s=stems.find(x=>x.ref===ref);await batch(s.sends.map((amount,i)=>({type:'set_track_send',track_ref:ref,return:i,amount})))}
async function toggleMute(ref){const s=stems.find(x=>x.ref===ref);s.muted=!s.muted;const b=document.querySelector('#m-'+ref);b.textContent='M '+(s.muted?'ON':'OFF');b.classList.toggle('onM',s.muted);try{await batch([{type:'set_track_mute',track_ref:ref,muted:!!s.muted}])}catch(e){s.muted=!s.muted}}
async function toggleSolo(ref){const s=stems.find(x=>x.ref===ref);s.soloed=!s.soloed;const b=document.querySelector('#so-'+ref);b.textContent='S '+(s.soloed?'ON':'OFF');b.classList.toggle('onS',s.soloed);try{await batch([{type:'set_track_solo',track_ref:ref,soloed:!!s.soloed}])}catch(e){s.soloed=!s.soloed}}
function renderReturns(){document.querySelector('#returnGrid').innerHTML=returns.map(r=>{const st=stateFor(c=>['set_return_volume','set_return_pan'].includes(c.command_type)&&c.payload.return===r.i);return `<article class="card"><div class="head"><div><span class="muted">RETURN ${r.l}</span><div class="name">${r.name}</div></div>${badge(st)}</div><p class="muted">${r.desc}</p><div class="control"><label><span>Volume target</span><span id="rv-${r.i}">${r.vol.toFixed(2)}</span></label><input type="range" min="0" max="1" step=".01" value="${r.vol}" oninput="returns[${r.i}].vol=+this.value;document.querySelector('#rv-${r.i}').textContent=(+this.value).toFixed(2)"></div><div class="control"><label><span>Pan target</span><span id="rp-${r.i}">${r.pan.toFixed(2)}</span></label><input type="range" min="-1" max="1" step=".01" value="${r.pan}" oninput="returns[${r.i}].pan=+this.value;document.querySelector('#rp-${r.i}').textContent=(+this.value).toFixed(2)"></div><button class="btn" style="width:100%;margin-top:10px" onclick="applyReturn(${r.i})">APPLY RETURN</button></article>`}).join('');setDisabled()}
async function applyReturn(i){const r=returns[i];await batch([{type:'set_return_volume',return:i,volume:r.vol},{type:'set_return_pan',return:i,pan:r.pan}])}
async function applyPremix(){const items=[];for(const s of stems){items.push({type:'set_track_volume',track_ref:s.ref,volume:s.vol},{type:'set_track_pan',track_ref:s.ref,pan:s.pan});s.sends.forEach((amount,i)=>items.push({type:'set_track_send',track_ref:s.ref,return:i,amount}))}await batch(items)}
async function loadHistory(){try{const r=await fetch('/api/commands?limit=100',{headers:headers()});const d=await r.json();if(!r.ok)throw Error(d.error);commands=d.commands;document.querySelector('#commandMetric').textContent=commands.length;document.querySelector('#historyList').innerHTML=commands.slice(0,20).map(c=>`<div class="event"><b>${esc(c.command_type)}</b><code>${esc(c.id)}</code><span class="${c.status}">${esc(c.status)}</span>${c.error?`<small class="error">${esc(c.error)}</small>`:''}</div>`).join('')||'<div class="card muted">No commands yet</div>';renderMixer();renderReturns()}catch(e){document.querySelector('#globalError').textContent=e.message}}
async function refreshAll(){try{const h=await fetch('/health').then(r=>r.json());const age=h.last_ack_at?Math.max(0,Math.floor((Date.now()-new Date(h.last_ack_at).getTime())/1000)):null;const fresh=h.max_receiver_seen&&age!==null&&age<=60;document.querySelector('#bridgePill').className='pill confirmed';document.querySelector('#bridgePill').textContent='Bridge v'+h.version;document.querySelector('#bridgeMetric').textContent='Online';document.querySelector('#receiverPill').className='pill '+(fresh?'confirmed':h.max_receiver_seen?'pending':'');document.querySelector('#receiverPill').textContent=fresh?'Receiver confirmed':h.max_receiver_seen?'ACK stale · '+age+'s':'Receiver waiting';document.querySelector('#receiverMetric').textContent=fresh?'Fresh':h.max_receiver_seen?'Stale':'None';document.querySelector('#modePill').textContent=h.approval_required?'Approval':'Autonomous';document.querySelector('#ackMetric').textContent=age===null?'—':age+'s ago';await loadHistory()}catch(e){document.querySelector('#bridgePill').className='pill error';document.querySelector('#bridgePill').textContent='Bridge offline';document.querySelector('#bridgeMetric').textContent='Offline';document.querySelector('#globalError').textContent=e.message}}
renderMixer();renderReturns();refreshAll();setInterval(refreshAll,3000);
</script></body></html>'''
